INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(52311, 'Isaiah 29:4', 'Isaiah', 29, 4, 'اورشلیم به د ارواحګانو په ښار بدل شي او د خلکو د زګېرویو اواز به لکه د مړو د ارواحګانو د اواز په شان وي چې د ځمکې د لاندې څخه ښه نه اورېدل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_4.mp3', '', 1761754199, 1761754199),
(52312, 'Isaiah 29:5', 'Isaiah', 29, 5, 'نو ای اورشلیمه، ټول پردي قومونه چې په تا باندې حمله وکړي، هغوی به د دوړو په شان والوزي او بې رحمه لښکرې به د بوسو په شان په هوا کې لېرې یووړل شي. نو ناڅاپه او سمدلاسه به', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_5.mp3', '', 1761754199, 1761754199),
(52313, 'Isaiah 29:6', 'Isaiah', 29, 6, 'مطلق قادر څښتن به ستاسو د ژغورنې دپاره راشي. د هغه سره به تندر، برېښنا، زلزله، لوی شور، بوړبوړکۍ، توفان او تباه کوونکي اور وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_6.mp3', '', 1761754199, 1761754199),
(52314, 'Isaiah 29:7', 'Isaiah', 29, 7, 'نو بیا ټول هغه قومونه چې د قربانۍ د لوی ځای یعنې اورشلیم او د هغه د لوړې کلا په ضد حمله کوي او ښار کلابندوي، هغوی به لکه د شپې د خوب د لیدلو او یا د رویا په شان له سترګو پناه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_7.mp3', '', 1761754199, 1761754199),
(52315, 'Isaiah 29:8', 'Isaiah', 29, 8, 'هغوی به لکه د یو داسې کس په شان وي چې د لوږې له لاسه مري او په خوب کې ویني چې خوراک کوي خو وږی راپاڅیږي، یا لکه څوک چې له تندې مري او په خوب کې ویني چې اوبه څښي، خو تږی راپاڅېږي او ستونی یې وچ وي. د هغو ټولو قومونو حالت به چې په اورشلیم د حملې دپاره راټول شوي دي، همداسې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_8.mp3', '', 1761754199, 1761754199),
(52316, 'Isaiah 29:9', 'Isaiah', 29, 9, 'خپلې بې عقلۍ ته دوام ورکړئ او همداسې ړانده اوسئ. بې له شرابو نشه اوسئ. پرته د شرابو د څښلو نه په لاره زنګېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_9.mp3', '', 1761754199, 1761754199),
(52317, 'Isaiah 29:10', 'Isaiah', 29, 10, 'ځکه څښتن تاسو په درانه خوب ویده کړي یئ. نبیان باید د خلکو سترګې اوسي، خو خدای د هغوی سترګې پټې کړې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_10.mp3', '', 1761754199, 1761754199),
(52318, 'Isaiah 29:11', 'Isaiah', 29, 11, 'ټوله رویا به درته لکه د یو مهر شوي کتاب په شان وي او نه شئ کولای په هغه پوه شئ، هغه که سواد لرونکي سړي ته هم ورکړئ چې هغه ولولي، وایي به: «زه یې نه شم لوستلی، ځکه چې هغه مهر شوی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_11.mp3', '', 1761754199, 1761754199),
(52319, 'Isaiah 29:12', 'Isaiah', 29, 12, 'که هغه کتاب یو داسې کس ته ورکړئ چې سواد ونه لري او د هغه څخه وغواړئ چې هغه ولولئ، وبه وایي: «زه یې نه شم لوستلی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_12.mp3', '', 1761754199, 1761754199),
(52320, 'Isaiah 29:13', 'Isaiah', 29, 13, 'څښتن وویل: «دا خلک تش په خبرو زما عبادت کوي، خو زړونه یې په کوم بل ځای کې دي. د هغوی عبادت یوازې د انساني حکمونو څخه الهام اخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_13.mp3', '', 1761754199, 1761754199),
(52321, 'Isaiah 29:14', 'Isaiah', 29, 14, 'په دې خاطر زه به یوځل بیا په خپلو عجیبه او فوق العاده کارونو هغوی ته ټکان ورکړم. څوک چې پوه وي هغه به ناپوه شي او د هغوی ټوله هوښیاري به له منځه لاړه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_14.mp3', '', 1761754199, 1761754199),
(52322, 'Isaiah 29:15', 'Isaiah', 29, 15, 'افسوس د هغه چا په حال چې خپلې نقشې د څښتن څخه پټوي! هغوی خپلې نقشې په تیاره کې عملي کوي او وایي: «څوک کولای شي مونږ وویني؟ څوک پوهیږي چې مونږ څه کوو؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_15.mp3', '', 1761754199, 1761754199),
(52323, 'Isaiah 29:16', 'Isaiah', 29, 16, 'هغوی سرچپه فکر کوي او د کلال او د منګي په فرق نه پوهیږي. ایا جوړ شوی شی خپل جوړوونکي ته ویلی شي: «تا زه نه یم جوړ کړی» یا ووایي: «ته په هېڅ هم نه پوهېږې»؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_16.mp3', '', 1761754199, 1761754199),
(52324, 'Isaiah 29:17', 'Isaiah', 29, 17, 'په ډېر لنډ وخت کې به د لبنان د ځنګل نه حاصلخیزه پټي جوړ شي او د پټیو نه به ځنګل جوړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_17.mp3', '', 1761754199, 1761754199),
(52325, 'Isaiah 29:18', 'Isaiah', 29, 18, 'کله چې هغه ورځ راشي کوم کتاب چې په لوړ اواز سره لوستل کیږي نو کاڼه به یې اورېدلی شي او هغه ړانده چې په تیاره او تورتم کې ژوند تېروي، د هغوی سترګې به وغړیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_18.mp3', '', 1761754199, 1761754199),
(52326, 'Isaiah 29:19', 'Isaiah', 29, 19, 'څښتن به یوځل بیا مظلومان خوشحاله کړي او غریبان به د اسراییلو د سپېڅلي خدای له امله خوښي وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_19.mp3', '', 1761754199, 1761754199),
(52327, 'Isaiah 29:20', 'Isaiah', 29, 20, 'د هغو خلکو ژوند به پای ته ورسیږي چې ظلم کوي او په خدای باندې ملنډې وهونکي به له منځه لاړ شي. هغه خلک به تباه شي چې بدې نقشې جوړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_20.mp3', '', 1761754199, 1761754199),
(52328, 'Isaiah 29:21', 'Isaiah', 29, 21, 'څښتن به هغه کسان له منځه یوسي چې د دروغو په ویلو سره یو بې ګناه انسان مجرم ګڼي، جنایت کوونکو ته د سزا د ورکولو مخنیوی کوي او په محکمه کې د بې ګناه خلکو حق خوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_21.mp3', '', 1761754199, 1761754199),
(52329, 'Isaiah 29:22', 'Isaiah', 29, 22, 'نو په دې خاطر څښتن چې ابراهیم یې د کړاوونو څخه وژغوره، د یعقوب د اولادې په اړه داسې وایي: «د یعقوب قوم به نور نه بې عزته کیږي او د هغوی مخونه به نور له شرمه نه سره کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_22.mp3', '', 1761754199, 1761754199),
(52330, 'Isaiah 29:23', 'Isaiah', 29, 23, 'کله چې زه هغوی ته اولادونه ورکړم او هغوی هغه وویني، نو بیا به دا ومني چې زه د اسراییلو سپېڅلی خدای یم. هغوی به له وېرې زما درناوی کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_23.mp3', '', 1761754199, 1761754199),
(52331, 'Isaiah 29:24', 'Isaiah', 29, 24, 'څوک چې بې لارې کیږي، هغوی به په حقیقت پوه شي او هغه کسان چې ګیله لري هغوی به تعلیم ومني.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah29_verse_24.mp3', '', 1761754199, 1761754199),
(52332, 'Ecclesiastes 6:1', 'Ecclesiastes', 6, 1, 'ما د اسمان لاندې بله بدبختي هم لیدلې ده چې د انسان په اوږو یې دروند بار ایښی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes6_verse_1.mp3', '', 1761754199, 1761754199),
(52333, 'Ecclesiastes 6:2', 'Ecclesiastes', 6, 2, 'یو سړي ته خدای مال، دولت او عزت ورکړی دی ترڅو له ټولو هغو شیانو څخه بې‌برخې نه وي چې زړه یې غواړي، خو خدای ورته دا قدرت نه دی ورکړی چې له هغو څخه وخوري او د هغه په ځای یو پردی سړی له هغو څخه خوري او ترې خوند اخلي. نو دا حالت لوګی او پوکی او لویه بدبختي ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes6_verse_2.mp3', '', 1761754199, 1761754199),
(52334, 'Ecclesiastes 6:3', 'Ecclesiastes', 6, 3, 'که چېرې یو سړی سل ماشومان ولري او حتی ډېر کلونه عمر وکړي او د ژوند ورځې یې ډېرې زیاتې وي، خو که هغه د خپل ژوند له نعمتونو څخه خوشحاله نه وي او په عزت سره ښخ نه شي، نو زه دا وایم چې هغه ماشوم ترې ښه دی چې مړ زېږېدلی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes6_verse_3.mp3', '', 1761754199, 1761754199),
(52335, 'Ecclesiastes 6:4', 'Ecclesiastes', 6, 4, 'ځکه، مړ زېږېدلی ماشوم نړۍ ته د لوګي او پوکي په شان راځي، په تیارې کې بېرته ځي او په هماغه تیارې کې یې نوم فنا کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes6_verse_4.mp3', '', 1761754199, 1761754199),
(52336, 'Ecclesiastes 6:5', 'Ecclesiastes', 6, 5, 'همدا شان هغه ماشوم لا د لمر روښنایي هم لیدلی نه دی او نه هم هغه پېژني، خو له هغه سړي نه زیات ارام دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes6_verse_5.mp3', '', 1761754199, 1761754199),
(52337, 'Ecclesiastes 6:6', 'Ecclesiastes', 6, 6, 'که هغه سړی دوه وارې او هر وار زر کاله ژوند وکړي، خو که د خپل ژوند نه خوند وانخلي نو څه ګټه لري؟ ایا په پای کې به دواړه یو ځای ته لاړ نه شي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes6_verse_6.mp3', '', 1761754199, 1761754199),
(52338, 'Ecclesiastes 6:7', 'Ecclesiastes', 6, 7, 'د انسان ټول زحمتونه د ګېډې دپاره وي خو د هغه ګېډه هېڅکله نه مړیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes6_verse_7.mp3', '', 1761754199, 1761754199),
(52339, 'Ecclesiastes 6:8', 'Ecclesiastes', 6, 8, 'په حقیقت کې، یو هوښیار سړی له یو کم‌عقل نه څه لوړوالی لري؟ که غریب سړی پوه شي چې له خلکو سره ښه چلند وکړي نو دا هغه ته څه ګټه لري؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes6_verse_8.mp3', '', 1761754199, 1761754199),
(52340, 'Ecclesiastes 6:9', 'Ecclesiastes', 6, 9, 'هغه سترګې چې په قناعت مړې وي له هغه ګېډې نه ښې دي چې تل وږې وي نو دا حالت هم لوګی او پوکی او په باد پسې منډې وهل دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes6_verse_9.mp3', '', 1761754199, 1761754199),
(52341, 'Ecclesiastes 6:10', 'Ecclesiastes', 6, 10, 'هرڅه چې اوس موجود دي په هغو له پخوا نه نوم ایښودل شوی او دا چې انسان څه دی هغه ټولو ته معلوم دی نو هغه نه شي کولای هغه چاته په بحث کې ماتې ورکړي چې ترې نه قوي دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes6_verse_10.mp3', '', 1761754199, 1761754199),
(52342, 'Ecclesiastes 6:11', 'Ecclesiastes', 6, 11, 'ځکه څومره چې خبرې او بحثونه زیاتیږي نو هغومره ډېر لوګي او پوکي پیدا کیږي او دا انسان ته څه ګټه لري؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes6_verse_11.mp3', '', 1761754199, 1761754199),
(52343, 'Ecclesiastes 6:12', 'Ecclesiastes', 6, 12, 'نو په حقیقت کې، څوک پوهیږي چې د انسان دپاره د هغه د ژوند په لنډه موده کې چې د لوګي او پوکي په شان دی او د سیوري په څېر تېریږي، څه شی ښه دی. څوک کولای شي هغه ته ووایي چې راتلونکی به د اسمان لاندې څه ډول وي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes6_verse_12.mp3', '', 1761754199, 1761754199),
(52344, 'Nehemiah 11:1', 'Nehemiah', 11, 1, 'نو د قوم مشران په اورشلیم کې ځای په ځای شول او نورو خلکو پچه واچوله چې د هرو لسو کورنیو څخه دې یوه کورنۍ غوره شي او هغه دې د اورشلیم په سپېڅلي ښار کې واوسیږي او پاتې دې په نورو ښارګوټو کې واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_1.mp3', '', 1761754199, 1761754199),
(52345, 'Nehemiah 11:2', 'Nehemiah', 11, 2, 'هر سړی چې په خپله خوښه حاضرېده چې په اورشلیم کې واوسیږي، خلکو د هغه دپاره د برکت غوښتنه کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_2.mp3', '', 1761754199, 1761754199),
(52346, 'Nehemiah 11:3', 'Nehemiah', 11, 3, 'د اسراییلو خلک، کاهنان، لاویان، د خدای د کور خدمتګاران او د سلیمان د خدمتګارانو اولاده د یهودا په ښارګوټو کې په خپلو ځمکو کې اوسېدل. دا د یهودا د ولایت د مشرانو لست دی چې په اورشلیم کې اوسېدل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_3.mp3', '', 1761754199, 1761754199),
(52347, 'Nehemiah 11:4', 'Nehemiah', 11, 4, 'په اورشلیم کې د یهودا او بنیامین د قبیلو ځینې غړي اوسېدل چې هغه دا وو: عتایا چې د عزیا زوی ؤ او د زکریا لمسی ؤ. د هغه په نورو نیکونو کې امریا، شفطیا او مهللییل چې د یهودا د زوی فارص اولاده ده، شامل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_4.mp3', '', 1761754199, 1761754199),
(52348, 'Nehemiah 11:5', 'Nehemiah', 11, 5, 'معسیا چې د باروک زوی او د کلحوزه لمسی ؤ. د هغه په نورو نیکونو کې حزایا، عدایا، یویاریب او زکریا چې د یهودا د زوی شیله اولاده ده، شامل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_5.mp3', '', 1761754199, 1761754199),
(52349, 'Nehemiah 11:6', 'Nehemiah', 11, 6, 'د فارص د اولادې څخه څلور سوه اته شپېته تکړه سړي چې په اورشلیم کې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_6.mp3', '', 1761754199, 1761754199),
(52350, 'Nehemiah 11:7', 'Nehemiah', 11, 7, 'د بنیامین د قبیلې غړي: سلو چې د مشلام زوی او د یوعید لمسی ؤ. د هغه په نورو نیکونو کې فدایا، قولایا، معسیا، ایتییل او اشعیا شامل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_7.mp3', '', 1761754199, 1761754199),
(52351, 'Nehemiah 11:8', 'Nehemiah', 11, 8, 'د سلو نه وروسته جبای او سلای. ټول نهه سوه اته ویشت تنه بنیامینیان په اورشلیم کې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_8.mp3', '', 1761754199, 1761754199),
(52352, 'Nehemiah 11:9', 'Nehemiah', 11, 9, 'د زکري زوی یوییل د هغوی مشر ؤ او یهودا د هسنواه زوی په ښار کې د هغه مرستیال ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_9.mp3', '', 1761754199, 1761754199),
(52353, 'Nehemiah 11:10', 'Nehemiah', 11, 10, 'کاهنان: یدعیا د یویاریب زوی او یاکین.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_10.mp3', '', 1761754199, 1761754199),
(52354, 'Nehemiah 11:11', 'Nehemiah', 11, 11, 'سرایا چې لوی کاهن ؤ، د حلقیا زوی او د مشلام لمسی ؤ. د هغه په نیکونو کې صادوق، مرایوت او اخیطوب شامل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_11.mp3', '', 1761754199, 1761754199),
(52355, 'Nehemiah 11:12', 'Nehemiah', 11, 12, 'د دې طایفې څخه اته سوه دوه ویشت تنو د خدای په کور کې خدمت کاوه. عدایا چې د یروحام زوی او د فللیا لمسی ؤ. د هغه په نیکونو کې امصي، زکریا، فشحور او ملکیا شامل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_12.mp3', '', 1761754199, 1761754199),
(52356, 'Nehemiah 11:13', 'Nehemiah', 11, 13, 'د دې طایفې څخه دوه سوه دوه څلوېښت تنه د کورنیو مشران وو. عمشیسای د عزرییل زوی او د اخزای لمسی ؤ. د هغه په نیکونو کې مشلیموت او یمیر شامل وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_13.mp3', '', 1761754199, 1761754199),
(52357, 'Nehemiah 11:14', 'Nehemiah', 11, 14, 'د دې طایفې څخه یو سلو اته ویشت زړور جنګیالي وو. د هغوی مشر زبدي ییل د هجدولیم زوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_14.mp3', '', 1761754199, 1761754199),
(52358, 'Nehemiah 11:15', 'Nehemiah', 11, 15, 'لاویان: شمعیه د حشوب زوی او د عزریقام لمسی ؤ. حشبیا او بوني د هغه نیکونه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_15.mp3', '', 1761754199, 1761754199),
(52359, 'Nehemiah 11:16', 'Nehemiah', 11, 16, 'شبتای او یوزاباد مشران لاویان وو او دوی د هغو کارونو مسوولان وو چې د خدای له کور څخه دباندې به تر سره کېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_16.mp3', '', 1761754199, 1761754199),
(52360, 'Nehemiah 11:17', 'Nehemiah', 11, 17, 'متنیا د میکا زوی او د زبدي لمسی ؤ چې د اساف اولاده وه. هغه د شکرګزارۍ د دعا د سندرې په ویلو سره د خدای د کور د سندرغاړو د ډلې مشري کوله. بقبقېا د متنیا مرستیال ؤ. عبدا د شموع زوی او د جلال لمسی ؤ چې د یدوتون د اولادې څخه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_17.mp3', '', 1761754199, 1761754199),
(52361, 'Nehemiah 11:18', 'Nehemiah', 11, 18, 'د اورشلیم په سپېڅلي ښار کې ټول دوه سوه او څلور اتیا تنه لاویان اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_18.mp3', '', 1761754199, 1761754199),
(52362, 'Nehemiah 11:19', 'Nehemiah', 11, 19, 'د خدای د کور ساتونکي: عقوب، طلمون او د هغوی خپلوان چې ټول یو سلو دوه اویا تنه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_19.mp3', '', 1761754199, 1761754199),
(52363, 'Nehemiah 11:20', 'Nehemiah', 11, 20, 'د اسراییلو نور خلک او پاتې کاهنان او لاویان د خپلو نیکونو په جایدادونو کې د یهودا په نورو ښارګوټو کې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_20.mp3', '', 1761754199, 1761754199),
(52364, 'Nehemiah 11:21', 'Nehemiah', 11, 21, 'د خدای د کور خدمتګاران د اورشلیم په هغې برخې کې اوسېدل چې د عوفل په نوم یادېده او هغوی د صیحا او جشفا تر نظر لاندې کار کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_21.mp3', '', 1761754199, 1761754199),
(52365, 'Nehemiah 11:22', 'Nehemiah', 11, 22, 'عزي د باني زوی او د حشبیا لمسی ؤ، هغه د هغو لاویانو مشر ؤ چې په اورشلیم کې اوسېدل. د هغه په نیکونو کې متنیا او میکا شامل وو او میکا د اساف د طایفې څخه ؤ چې نوموړې طایفې د خدای په کور کې د موسیقۍ مسوولیت په غاړه درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_22.mp3', '', 1761754199, 1761754199),
(52366, 'Nehemiah 11:23', 'Nehemiah', 11, 23, 'د سندرغاړو ورځنی فعالیت د فارس پاچا د امر او اصولو سره سم تر سره کېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_23.mp3', '', 1761754199, 1761754199),
(52367, 'Nehemiah 11:24', 'Nehemiah', 11, 24, 'فتحیا د مشیزبییل زوی چې د زارح د طایفې او د یهودا د قبیلې څخه ؤ، د فارس په دربار کې د اسراییلو د خلکو استازی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_24.mp3', '', 1761754199, 1761754199),
(52368, 'Nehemiah 11:25', 'Nehemiah', 11, 25, 'ډېر خلک په هغو ښارګوټو کې اوسېدل چې د هغوی کروندو ته نژدې وو. د یهودا د قبیلې خلک په قریت اربع، دیبون او یقبصي ییل او د دغو ښارونو په نژدې کلیو کې اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_25.mp3', '', 1761754199, 1761754199),
(52369, 'Nehemiah 11:26', 'Nehemiah', 11, 26, 'همدارنګه هغوی د یشوع، مولاده، بیت فالط', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_26.mp3', '', 1761754199, 1761754199),
(52370, 'Nehemiah 11:27', 'Nehemiah', 11, 27, 'او د حزر شوعال په ښارونو او د بیرشبع په ښار او د هغه په شاوخوا کلیو کې هم اوسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_27.mp3', '', 1761754199, 1761754199),
(52371, 'Nehemiah 11:28', 'Nehemiah', 11, 28, 'هغوی د صقلغ او مکونه په ښارونو او د هغو په شاوخوا کلیو کې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_28.mp3', '', 1761754199, 1761754199),
(52372, 'Nehemiah 11:29', 'Nehemiah', 11, 29, 'په عین رمون، زرعه، یرموت،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_29.mp3', '', 1761754199, 1761754199),
(52373, 'Nehemiah 11:30', 'Nehemiah', 11, 30, 'زانوح، عدولام او د دغو ښارګوټو په نژدې کلیو کې اوسېدل. هغوی په لاخیش او نژدې کروندو او په عزیقه او د هغې په شاوخوا کلیو کې اوسېدل. په دې توګه د یهودا خلک په هغې سیمې کې اوسېدل چې د بیرشبع او د هنوم د درې ترمنځ پرته وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah11_verse_30.mp3', '', 1761754199, 1761754199),
